<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="referrer" content="strict-origin-when-cross-origin"><title>@yield('title', 'ORVIONART Yönetim')</title>
<style>
:root{color-scheme:dark;--bg:#0c1420;--line:#2b3b4c;--text:#f2f6fa;--muted:#aab9c8;--accent:#58d3cb;--gold:#d8bd80}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 12% 0,#1c3340 0,transparent 38%),var(--bg);color:var(--text);font:16px/1.55 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:var(--accent)}button,input{font:inherit}.wrap{width:min(1120px,calc(100% - 32px));margin:auto}.top{border-bottom:1px solid var(--line);background:#0c1420dd}.top-inner{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:16px}.brand{font-size:1.15rem;letter-spacing:.13em;font-weight:800}.brand span{color:var(--accent)}.pill{font-size:.78rem;border:1px solid var(--line);padding:5px 10px;border-radius:99px;color:var(--muted)}main{padding:42px 0 64px}.muted{color:var(--muted)}.eyebrow{text-transform:uppercase;letter-spacing:.16em;font-size:.75rem;color:var(--accent);font-weight:700}.panel{background:linear-gradient(145deg,#172534,#101a26);border:1px solid var(--line);border-radius:18px;padding:24px;box-shadow:0 18px 50px #0002}.login{max-width:480px;margin:5vh auto}.field{display:grid;gap:7px;margin:18px 0}.field label{font-size:.92rem;color:#dbe5ee}.field input{width:100%;padding:13px 14px;border-radius:10px;border:1px solid #405367;background:#0b131d;color:white}.field input:focus{outline:2px solid var(--accent);outline-offset:2px}.btn{display:inline-flex;justify-content:center;align-items:center;border:0;border-radius:10px;padding:12px 18px;background:var(--accent);color:#082020;font-weight:800;cursor:pointer;text-decoration:none}.btn.secondary{background:transparent;border:1px solid var(--line);color:var(--text)}.errors{background:#47242b;border:1px solid #85444e;color:#ffe1e4;padding:12px 16px;border-radius:10px}.hero{display:flex;align-items:flex-start;justify-content:space-between;gap:22px;flex-wrap:wrap}.hero h1{font-size:clamp(2rem,5vw,3.3rem);line-height:1.08;letter-spacing:-.04em;margin:10px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:28px}.module{padding:20px;border:1px solid var(--line);border-radius:14px;background:#111d29}.module h3{margin:0 0 8px}.status{display:inline-block;font-size:.74rem;border:1px solid #786b48;color:var(--gold);border-radius:99px;padding:3px 9px}.notice{margin-top:24px;padding:16px 18px;border-left:3px solid var(--gold);background:#211f19;color:#e7dfcb}.footer{padding-top:28px;color:#8192a3;font-size:.8rem}@media(max-width:760px){.grid{grid-template-columns:1fr}.panel{padding:19px}.top-inner{min-height:62px}.hero{display:block}}
